use vstd::prelude::*;

verus! {

fn concat(a: &Vec<u64>, b: &Vec<u64>) -> (result: Vec<u64>)
    requires
        a.len() <= 100,
        b.len() <= 100,
    ensures
        result.len() == a.len() + b.len(),
        forall|i: int| 0 <= i < a.len() ==> result[i] == a[i],
        forall|i: int| a.len() <= i < result.len() ==> result[i] == b[i - a.len()],
{
    let mut result: Vec<u64> = Vec::new();
    let mut i: usize = 0;

    while i < a.len()
        invariant
            i <= a.len(),
            result.len() == i,
            forall|j: int| 0 <= j < i as int ==> result[j] == a[j],
        decreases a.len() - i,
    {
        result.push(a[i]);
        i = i + 1;
    }

    let mut j: usize = 0;
    while j < b.len()
        invariant
            j <= b.len(),
            result.len() == a.len() + j,
            forall|k: int| 0 <= k < a.len() ==> result[k] == a[k],
            forall|k: int| a.len() <= k < result.len() ==> result[k] == b[k - a.len()],
        decreases b.len() - j,
    {
        result.push(b[j]);
        j = j + 1;
    }

    result
}

}
